        uint hb = (h >> (8u * b)) & 0xFFu;
        uint lo = (by & 0xFu) | (((hb >> (2u * g)) & 1u) << 4);
        uint hi = (by >> 4) | (((hb >> (2u * g + 1u)) & 1u) << 4);
        acc += (ds0 * float(lo) - dm0) * float(sA[k0 + b]);
        acc += (ds1 * float(hi) - dm1) * float(sA[k0 + 32u + b]);
    }
    return acc;
}
