#endif

    uint nqd = (pc.gemmK / QK) * QSDB;
    float acc0 = 0.0;
#if MODE == 0
    float acc1 = 0.0;
#endif
    for (uint d = lane; d < nqd; d += LPR) {
        acc0 += dotDword(rb0, d);
#if MODE == 0
        acc1 += dotDword(rb1, d);
#endif
    }

    acc0 = subgroupClusteredAdd(acc0, LPR);
#if MODE == 0
    acc1 = subgroupClusteredAdd(acc1, LPR);
#endif
    if (lane != 0u) {
