		blk := data[b*18:]
		d := f16At(blk, 0)
		lo := len(dst)
		dst = append(dst, make([]float32, 32)...)
		out := dst[lo:]
		for j := 0; j < 16; j++ {
			out[j] = d * float32(kvaluesIQ4NL[blk[2+j]&0xF])
			out[j+16] = d * float32(kvaluesIQ4NL[blk[2+j]>>4])
