// packQ41Row writes one row as ggml `block_q4_1`: a 32-element block with an
// fp16 scale, an fp16 min and 16 nibble pairs. 20 bytes, **5.0 bits a
// weight**, and it is `packQ51Row` with the plane of fifth bits deleted —
// the same asymmetric `scale*l + min` reconstruction, the same 0..15 / 16..31
// split of the pairs, fifteen levels instead of thirty-one.
//
// The fit is the same one, for the same reason: `quantize_row_q4_1_ref` is
// plain min/max because the legacy quants were never wired to an importance
// matrix, and here the matrix is available, so the calibrated arm fits
// (scale, min) with `makeQkxQuants` and `rtn` is ggml's own path. The
// asymmetry `packQ51Row` names carries over unchanged — `makeQkxQuants`
// clamps the min to zero and ggml's reference keeps the block's true min.
func packQ41Row(dst []byte, row, qw []float32) {
	const g = 32
	var lv, laux [g]uint8
	var w [g]float32
	for b := 0; b*g < len(row); b++ {
		blk := row[b*g : (b+1)*g]
		var d, min float32
		if qw != nil {
			var sum2 float32
			for _, v := range blk {
				sum2 += v * v
			}
			sigma2 := 2 * sum2 / float32(g)
			for i, v := range blk {
				w[i] = qw[b*g+i] * sqrt32(sigma2+v*v)
			}
			// Fifteen levels, and the same sweep constants every calibrated
			// fit in this vertical uses (`asymEnc`, `packQ51Row`).
			d, min = makeQkxQuants(blk, 15, w[:], lv[:], laux[:], -0.9, 0.05, 36)
		} else {
			lo, hi := blk[0], blk[0]
			for _, v := range blk {
				if v < lo {
					lo = v
				}
				if v > hi {
					hi = v
				}
			}
			d, min = (hi-lo)/15, -lo
		}
		// Chosen against the *stored* pair, as every other packer here does.
		dh, mh := safetensors.F32ToF16(d), safetensors.F32ToF16(-min)
		df, mf := safetensors.F16ToF32(dh), safetensors.F16ToF32(mh)
