		}
		binary.LittleEndian.PutUint16(rec[0:], dh)
		binary.LittleEndian.PutUint16(rec[2:], mh)
		for i, v := range blk {
			var l int
			if df != 0 {
				l = int(nearestInt((v - mf) / df))
			}
			if l < 0 {
				l = 0
			}
			if l > 15 {
				l = 15
			}
			if i < 16 {
				rec[4+i] |= byte(l)
			} else {
				rec[4+i-16] |= byte(l) << 4
