			}
		}
		rec := dst[b*18 : (b+1)*18]
		for i := range rec {
			rec[i] = 0
		}
		// ggml's GROUP_MAX_EPS. A block with no magnitude is a zero scale and
		// whatever nibbles the codebook search last left behind; here that is
		// the level nearest zero, which reconstructs to zero either way.
		if amax < 1e-15 {
			for i := range lv {
				lv[i] = uint8(bestIQ4NLIndex(values, 0))
			}
			packIQ4NLNibbles(rec[2:], lv[:])
			continue
		}
		// The sign convention is ggml's and it is not a typo: the calibrated
		// arm starts from `-max/values[0]` and the reference from
		// `max/values[0]`, and `values[0]` is -127 against a top level of
		// +113 — the codebook is not symmetric, so the two starts are two
		// different assignments rather than the same one mirrored.
		d := max / float32(values[0])
		if ntry > 0 {
			d = -max / float32(values[0])
		}
		id := 1 / d
		var sumqx, sumq2 float32
		for i, v := range blk {
			l := bestIQ4NLIndex(values, id*v)
			lv[i] = uint8(l)
			q := float32(values[l])
			sumqx += w[i] * q * v
			sumq2 += w[i] * q * q
		}
		if sumq2 > 0 {
			d = sumqx / sumq2
		} else {
			d = 0
		}
		best := d * sumqx
		for itry := -ntry; itry <= ntry; itry++ {
			id := (float32(itry) + float32(values[0])) / max
			sumqx, sumq2 = 0, 0
			for i, v := range blk {
				q := float32(values[bestIQ4NLIndex(values, id*v)])
				sumqx += w[i] * q * v
				sumq2 += w[i] * q * q
			}
			if sumq2 > 0 && sumqx*sumqx > best*sumq2 {
				d = sumqx / sumq2
				best = d * sumqx
			}
		}
		// The levels are re-derived from the winning scale on the calibrated
		// arm only — `quantize_row_iq4_nl_ref` keeps the assignment its first
		// pass made, which is the one difference between the two arms that is
		// not a weight.
		if ntry > 0 {
			id := float32(0)
			if d != 0 {
				id = 1 / d
			}
			for i, v := range blk {
				lv[i] = uint8(bestIQ4NLIndex(values, id*v))
			}
		}
		binary.LittleEndian.PutUint16(rec[0:], safetensors.F32ToF16(d))
		packIQ4NLNibbles(rec[2:], lv[:])
	}
}

// packIQ4NLNibbles is the pair split every block-32 format here uses:
// element j in the low nibble of byte j and element j+16 in its high one.
func packIQ4NLNibbles(dst []byte, lv []uint8) {
	for j := 0; j < 16; j++ {
		dst[j] = lv[j]&0xF | lv[j+16]&0xF<<4
	}
}

// bestIQ4NLIndex is ggml's `best_index_int8` over a sorted codebook: the
// level nearest x, by a binary search rather than a scan.
func bestIQ4NLIndex(values [16]int8, x float32) int {
	if x <= float32(values[0]) {
		return 0
	}
	if x >= float32(values[15]) {
		return 15
	}
	ml, mu := 0, 15
	for mu-ml > 1 {
		mav := (ml + mu) / 2
		if x < float32(values[mav]) {
			mu = mav
		} else {
			ml = mav
		}
	}
	if x-float32(values[mu-1]) < float32(values[mu])-x {
		return mu - 1
	}
	return mu
}
