			var ourErr, ggmlErr float64
			for j := range got {
				r, b := j/rec.k, (j%rec.k)/c.typ.BlockElems()
				d := float64(f16at(dst[r*rowBytes+b*c.typ.BlockBytes():][:2]))
				step := math.Abs(d)
				if c.typ == gguf.IQ4_NL {
					// The codebook's widest gap, in units of d: 113 - 89.
					step *= 24
				}
