					w = float64(rec.im[j%rec.k])
				}
				x := float64(rec.x[j])
				ourErr += w * (x - float64(got[j])) * (x - float64(got[j]))
				ggmlErr += w * (x - float64(want[j])) * (x - float64(want[j]))
			}
			pct := 100 * float64(diff) / float64(len(got))
