		// what says the difference is a rounding the GEMM does and not an
		// error this kernel makes.
		if rr.rms > rg.rms*1.05 {
			t.Errorf("%s is %.3e from ffn_out-3 where the GEMM is %.3e", name, rr.rms, rg.rms)
