	refTop := append([]int32(nil), g.TopK()...)
	for _, k := range MoERouterKernels() {
		if err := g.SetRouter(k); err != nil {
			t.Fatal(err)
		}
		if err := g.Run(0); err != nil {
			t.Fatal(err)
		}
