// perplexity run would read it as an accuracy cost.
func TestMoEBankTranscodeStagesLikeTheCheckpoint(t *testing.T) {
	if testing.Short() {
		t.Skip("stages two expert banks, 3.2 GB")
	}
	c, w, in, nTok, _ := moeFixtures4k(t)
	// P4b's plan, and P4c's: the second one narrows a **routed** tensor,
	// three-dimensional and 0.5 GB a layer, so its offset, its row stride and
	// its pipeline are a different path through the same code.
	spec := "gate_shexp=q4_k,up_shexp=q4_k,down_shexp=q5_1"
	subs := []struct {
		dst **gguf.Tensor
		to  gguf.Type
	}{
		{&w.GateShexpT, gguf.Q4_K},
		{&w.UpShexpT, gguf.Q4_K},
		{&w.DownShexpT, gguf.Q5_1},
	}
	if p4c := os.Getenv("LLM_TEST_MOE_DOWN"); p4c != "" {
		spec, subs = "down_exps="+p4c, []struct {
			dst **gguf.Tensor
			to  gguf.Type
		}{{&w.Down.T, moeBankFormats[p4c]}}
	}
	plan, err := ParseMoEBankPlan(spec, "imatrix")
	if err != nil {
		t.Fatal(err)
	}

	// The control's weights: the same tensors, already narrowed, with
	// the plan off so nothing in the staging path can treat them specially.
	pre := w
	for i := range subs {
		sub := subs[i]
		// `pre` is a copy of `w`, so redirect the substitution at it.
		switch sub.dst {
		case &w.GateShexpT:
			sub.dst = &pre.GateShexpT
		case &w.UpShexpT:
			sub.dst = &pre.UpShexpT
		case &w.DownShexpT:
			sub.dst = &pre.DownShexpT
		case &w.Down.T:
			sub.dst = &pre.Down.T
		}
		src := *sub.dst
		data, err := TranscodeMoE(src, sub.to, "imatrix")
		if err != nil {
			t.Fatal(err)
		}
		*sub.dst = &gguf.Tensor{Name: src.Name, Type: sub.to, Dims: src.Dims, Data: data}
	}

	dev, done := newTestDevice(t)
	defer done()
	run := func(ws MoEWeights, p MoEBankPlan) ([]float32, []float32, []float32) {
		g, err := NewMoEGPU(dev, c, nTok, []MoEWeights{ws}, WithMoEBankPlan(p))
		if err != nil {
			t.Fatal(err)
		}
		defer g.Destroy()
		if gate, up, down := g.Formats(0); testing.Verbose() {
			shUp, shDown := g.SharedBytes(0)
			t.Logf("plan %s: routed %s/%s/%s, shared expert %d + %d bytes a layer",
				p, gate, up, down, shUp, shDown)

