#elif QFMT == FMT_IQ4NL
// IQ4_NL is eighteen bytes, so it lands on Q8_0's rotating window — every
// other block starts at an offset of 2 mod 4 — over Q4_1's nibble pairs.
float dotDword(uint rb, uint d) {
    uint m = d >> 2;
    uint qq = d & 3u;
    uint blk = rb + m * QB;
    uint hw = blk >> 2;
    vec2 dd = unpackHalf2x16(qbank[hw]);
    float dq = ((blk & 2u) == 0u) ? dd.x : dd.y;
    uint base = blk + 2u;
    uint bw = (base >> 2) + qq;
    uint w = ((base & 2u) != 0u) ? ((qbank[bw] >> 16) | (qbank[bw + 1u] << 16)) : qbank[bw];
    uint k0 = m * QK;
    uint j0 = qq * 4u;
    float acc = 0.0;
    [[unroll]] for (uint b = 0u; b < 4u; ++b) {
        uint j = j0 + b;
        uint by = (w >> (8u * b)) & 0xFFu;
        acc += iq4nlValue(by & 0xFu) * dq * float(sA[k0 + j]);
        acc += iq4nlValue(by >> 4) * dq * float(sA[k0 + j + 16u]);
    }
    return acc;
}
#else

