	// And the planes are where the shaders look for them: nb halves, then
	// nb sixteen-byte groups.
	nb := k / 32
	for b := 0; b < nb; b++ {
		if got, want := planar[b*2:b*2+2], ggml[b*18:b*18+2]; !bytes.Equal(got, want) {
